using "/ws/EvtWorks/cod-project/tests/cod/language/procedure-library.cod" read;
effect @bias <- 20;
proc alternate(value::i64)->i64 { @bias * 100 + value }
function argument_value(unused::proc(i64)->i64, value::i64)::i64 { value }
